static long (*emit)(void *, void *, jm_u64, void *, jm_u64) = (void *)25;
#define INLINE static __attribute__((always_inline)) inline

INLINE int field(struct jm_event *e, void *dst, jm_u32 n, jm_u64 address)
{
    if (e->reads >= 80 || n > 64 || e->source_bytes > 2048 - n) {
        e->status = JM_BUDGET;
        return -1;
    }
    e->reads++; e->source_bytes += n;
    if (read_mem(dst, n, address)) {
        e->status = JM_READ_FAILED;
        return -1;
    }
    return 0;
}

INLINE int bytes(struct jm_event *e, jm_u64 head,
        jm_u32 offset, jm_u32 length)
{
    struct tm_frag frag = {0};
    jm_u32 copied = 0;
    if (length > 64)
        return -1;
#pragma unroll
    for (int i = 0; i < 4; i++) {
        if (copied == length)
            return 0;
        if (!head) { e->status = TM_INVALID_CACHE; return -1; }
        if (field(e, &frag, sizeof frag, head))
            return -1;
        if (offset < frag.len) {
            jm_u32 n = frag.len - offset;
            if (n > length - copied) n = length - copied;
            if (copied > 63 || n > 64 - copied) return -1;
            if (field(e, e->value + copied, n,
                        frag.base + frag.offset + offset))
                return -1;
            copied += n; offset = 0;
        } else offset -= frag.len;
        head = frag.next;
    }
    if (copied == length) return 0;
    e->status = JM_BUDGET;
    return -1;
}

INLINE int token(struct jm_event *e, struct mi_view *v,
        jm_u32 index, struct tm_token *t)
{
    e->status = TM_INVALID_CACHE;
    if (index >= v->used || field(e, t, 20,
                v->tokens + (jm_u64)index * 20))
        return -1;
    if (t->start < 0 || t->end < t->start ||
            (jm_u32)t->end > v->length || t->size < 0)
        return -1;
    return 0;
}

/* Full bounded root scan: do not select the first of two literal IDs. */
INLINE int member(struct jm_event *e, struct mi_view *v,
        struct tm_token *t)
{
    if (token(e, v, 0, t)) return -1;
    if (t->type != 1) { e->status = JM_OUT_OF_SCOPE; return -1; }
    if (t->size > 4) { e->status = JM_BUDGET; return -1; }
    jm_u32 count = t->size, end = t->end, minimum = t->start;
    jm_u32 index = 1, selected = 0, seen = 0;
#pragma unroll
    for (int i = 0; i < 4; i++) {
        if ((jm_u32)i >= count) break;
        if (token(e, v, index, t)) return -1;
        if (t->type != 3 || (jm_u32)t->start < minimum ||
                (jm_u32)t->end > end)
            return -1;
        minimum = t->end;
        int match = 0;
        if (t->end - t->start == 2) {
            if (bytes(e, v->head, t->start, 2)) return -1;
            match = e->value[0] == 'i' && e->value[1] == 'd';
            __builtin_memset(e->value, 0, sizeof e->value);
        }
        index++;
        if (token(e, v, index, t)) return -1;
        if ((jm_u32)t->start < minimum || (jm_u32)t->end > end)
            return -1;
        minimum = t->end;
        if (match) { selected = index; seen++; }
        if ((jm_u32)(i + 1) < count &&
                (t->sibling <= (int)index || (jm_u32)t->sibling >= v->used))
            return -1;
        index = t->sibling;
    }
    if (seen != 1) {
        e->status = seen ? MI_AMBIGUOUS : MI_MISSING;
        return -1;
    }
    return token(e, v, selected, t);
}

/* Bounded JSON-number grammar, retaining spelling instead of converting it.
 * State 0=start, 1=after sign, 2=zero, 3=integer, 4=dot,
 * 5=fraction, 6=exponent marker, 7=exponent sign, 8=exponent digits. */
INLINE int number(struct jm_event *e, jm_u32 n)
{
    jm_u32 state = 0;
#pragma clang loop unroll(disable)
    for (jm_u32 i = 0; i < 64; i++) {
        if (i >= n) break;
        unsigned char c = e->value[i];
        int digit = c >= '0' && c <= '9';
        if (state == 0 && c == '-') state = 1;
        else if ((state == 0 || state == 1) && digit)
            state = c == '0' ? 2 : 3;
        else if (state == 3 && digit) state = 3;
        else if ((state == 2 || state == 3) && c == '.') state = 4;
        else if ((state == 4 || state == 5) && digit) state = 5;
        else if ((state == 2 || state == 3 || state == 5) &&
                (c == 'e' || c == 'E')) state = 6;
        else if (state == 6 && (c == '+' || c == '-')) state = 7;
        else if ((state == 6 || state == 7 || state == 8) && digit)
            state = 8;
        else return -1;
    }
    return state == 2 || state == 3 || state == 5 || state == 8 ? 0 : -1;
}

INLINE void extract(struct mi_ctx *ctx, struct jm_event *e)
{
    struct mi_view v = {0};
    union {
        struct { jm_u32 len, flags; jm_u64 head, tail; } raw;
        struct { jm_u32 capacity, limit; jm_u64 tokens; jm_u32 pos, used; } parser;
        struct tm_token t;
        jm_u64 root;
        jm_u32 valid;
    } s = {0};
    jm_u64 cache = 0;
    if (!ctx->arg[1]) return;
    if (field(e, &s.valid, 4, ctx->arg[1] + 88)) return;
    if ((s.valid & 0x24) != 0x24 || (s.valid & 0x1000)) {
        e->status = JM_OUT_OF_SCOPE; return;
    }
    if (field(e, &cache, 8, ctx->arg[1] + 24) || !cache) return;
    e->status = TM_INVALID_CACHE;
    if (field(e, &s.root, 8, cache) || !s.root ||
            field(e, &s.valid, 4, cache + 64) || s.valid != 1 ||
            field(e, &s.raw, 24, cache + 8)) return;
    v.head = s.raw.head; v.length = s.raw.len;
    if (field(e, &s.parser, 24, cache + 32)) return;
    v.tokens = s.parser.tokens; v.used = s.parser.used;
    if (!v.tokens || !v.used || v.used > s.parser.capacity) return;
    if (member(e, &v, &s.t)) return;
    e->status = MI_WRONG_TYPE;
    if (s.t.type != 3 && s.t.type != 4) return;
    jm_u32 n = s.t.end - s.t.start;
    e->original_length = n;
    if (s.t.type == 3) {
        e->getter_result = MI_STRING;
        if (n > 64) n = 64;
    } else if (!n || n > 64) {
        e->status = JM_OUT_OF_SCOPE; return;
    }
    if (bytes(e, v.head, s.t.start, n)) return;
    if (s.t.type == 4) {
        if (n == 4 && !__builtin_memcmp(e->value, "null", 4))
            e->getter_result = MI_NULL;
        else if (!number(e, n)) e->getter_result = MI_NUMBER;
        else return;
    }
    e->copied_length = n;
    e->status = n < e->original_length ? JM_TRUNCATED : JM_COMPLETE;
}

__attribute__((section("fentry/json_filter_handle_json_complete"), used))
jm_u64 message_id(struct mi_ctx *ctx)
{
    struct jm_event e = {0};
    struct mi_state fresh = {0}, *state = 0;
    struct ls_cfg_meta *meta = ls_cfg_get(0);
    struct mi_policy *policy;
    jm_u32 zero = 0;
    e.magic = MI_MAGIC; e.abi = 1; e.status = JM_UNAVAILABLE;
    e.monotonic_ns = clock_ns();
    if (!e.monotonic_ns) e.flags |= 8;
    if (!meta) { e.flags |= 1; goto output; }
    e.instance = meta->instance; e.revision = meta->revision;
    policy = ls_cfg_get(1);
    if (!policy || meta->schema != 1 || meta->entries != 1 || !policy->run ||
            policy->reserved[0] || policy->reserved[1] || policy->reserved[2]) {
        e.flags |= 1; goto output;
    }
    e.run = policy->run;
    state = lookup(&message_id_state, &zero);
    if (!state || state->instance != e.instance) {
        fresh.instance = e.instance;
        if (update(&message_id_state, &zero, &fresh, 0)) {
            e.flags |= 2; state = 0; goto output;
        }
        state = lookup(&message_id_state, &zero);
    }
    if (!state) { e.flags |= 2; goto output; }
    e.output_failures = state->failures;
    if (state->calls == ~0ull) e.flags |= 4;
    else e.sequence = ++state->calls;
    extract(ctx, &e);
output:
    if (e.status != JM_COMPLETE && e.status != JM_TRUNCATED) {
        __builtin_memset(e.value, 0, sizeof e.value);
        e.copied_length = 0;
    }
    if (emit(ctx, &metadata_events, 0, &e, sizeof e) && state &&
            state->failures != ~0ull) state->failures++;
    return 0;
}

